// Antigravity Workflow - Password Gate
// AES-GCM encrypted content, decrypted client-side via Web Crypto API

var GATE_SALT = "OJFT+Pwnz13kq8uhmjnikg==";
var GATE_IV = "fz01BCOrXu5pcw3W";
var GATE_CT = "";

async function decryptSection() {
  var password = document.getElementById('gate-password').value;
  var errorEl = document.getElementById('gate-error');
  var loadingEl = document.getElementById('gate-loading');
  var submitBtn = document.getElementById('gate-submit');
  var inputEl = document.getElementById('gate-password');
  errorEl.style.display = 'none';
  loadingEl.style.display = 'block';
  submitBtn.disabled = true;
  submitBtn.textContent = 'Unlocking...';
  inputEl.disabled = true;

  try {
    // Decode base64
    var salt = Uint8Array.from(atob(GATE_SALT), function(c) { return c.charCodeAt(0); });
    var iv = Uint8Array.from(atob(GATE_IV), function(c) { return c.charCodeAt(0); });
    var ct = Uint8Array.from(atob(GATE_CT), function(c) { return c.charCodeAt(0); });

    // Derive key via PBKDF2
    var keyMaterial = await crypto.subtle.importKey(
      'raw',
      new TextEncoder().encode(password),
      'PBKDF2',
      false,
      ['deriveKey']
    );

    var key = await crypto.subtle.deriveKey(
      {
        name: 'PBKDF2',
        salt: salt,
        iterations: 100000,
        hash: 'SHA-256'
      },
      keyMaterial,
      { name: 'AES-GCM', length: 256 },
      false,
      ['decrypt']
    );

    // Decrypt
    var decrypted = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: iv },
      key,
      ct
    );

    var plaintext = new TextDecoder().decode(decrypted);

    // Load marked.js if not available, then render
    if (typeof marked === 'undefined') {
      var script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/npm/marked/marked.min.js';
      script.onload = function() {
        renderContent(plaintext);
      };
      document.head.appendChild(script);
    } else {
      renderContent(plaintext);
    }

  } catch (e) {
    console.error('Decryption failed:', e);
    errorEl.style.display = 'block';
    loadingEl.style.display = 'none';
    submitBtn.disabled = false;
    submitBtn.textContent = 'Unlock';
    inputEl.disabled = false;
    inputEl.focus();
    return;
  }
}

function renderContent(plaintext) {
  var htmlContent = marked.parse(plaintext);
  var contentEl = document.getElementById('decrypted-content');
  contentEl.innerHTML = htmlContent;

  document.getElementById('protected-section').style.display = 'block';
  document.getElementById('password-gate').style.display = 'none';

  // Unlock scroll
  document.body.style.overflow = '';
  document.documentElement.style.overflow = '';

  // Re-run syntax highlighters if available
  if (typeof hljs !== 'undefined') {
    document.querySelectorAll('#decrypted-content pre code').forEach(function(block) {
      hljs.highlightElement(block);
    });
  }

  // Re-run MathJax if available
  if (typeof MathJax !== 'undefined' && MathJax.typesetPromise) {
    MathJax.typesetPromise([contentEl]);
  }
}

// Allow Enter key to submit + lock scroll on load
document.addEventListener('DOMContentLoaded', function() {
  // Lock scroll until unlocked
  document.body.style.overflow = 'hidden';
  document.documentElement.style.overflow = 'hidden';

  var input = document.getElementById('gate-password');
  if (input) {
    input.focus();
    input.addEventListener('keypress', function(e) {
      if (e.key === 'Enter') {
        decryptSection();
      }
    });
  }
});
